// Self-check: compares your variables with the page. Do not edit this file.
// A check that uses a missing variable throws an error, which counts as NOT YET.
(function () {
  const results = [];
  function check(name, fn, hint) {
    let ok = false;
    try { ok = fn(); } catch (e) { ok = false; }
    results.push({ name, ok, hint });
  }
  const products = document.querySelectorAll('.product');

  check('1. branchName is the <h1>', () => branchName === document.getElementById('branch-name'), 'Use document.getElementById with the id written in index.html.');
  check('2. firstProduct is the first product', () => firstProduct === products[0], 'querySelector returns the FIRST match. Remember the dot for a class.');
  check('3. allProducts holds every product', () => allProducts && allProducts.length === products.length && allProducts[0] === products[0], 'querySelectorAll returns all matches, as a NodeList.');
  check('4. lowStock holds only the low products', () => lowStock && lowStock.length === document.querySelectorAll('.product.low').length && [...lowStock].every(el => el.classList.contains('low')), 'Join two classes with no space between them.');
  check('5. mapLink is the directions link', () => mapLink === document.getElementById('directions'), 'An id selector starts with #.');
  check('6. mostExpensive is the right name', () => {
    let best = null;
    products.forEach(p => { if (!best || Number(p.dataset.price) > Number(best.dataset.price)) best = p; });
    return mostExpensive === best.textContent;
  }, 'Compare numbers, not text: "6600" < "705" is true for text! Use Number().');
  check('7. #status shows the product count', () => document.getElementById('status').textContent.trim() === `DOM ready: ${products.length} products found`, 'Use textContent and allProducts.length, not a typed number.');

  const list = document.getElementById('self-check');
  results.forEach(r => {
    const li = document.createElement('li');
    li.textContent = (r.ok ? 'PASS ' : 'NOT YET ') + r.name + (r.ok ? '' : ' (hint: ' + r.hint + ')');
    li.className = r.ok ? 'pass' : 'fail';
    list.append(li);
  });
  const passed = results.filter(r => r.ok).length;
  console.log(`Self-check: ${passed} of ${results.length} passed`);
})();
